async function trial(browser, id, outputDir, url, query, reset = true) {
  if (reset) await browser.resetForTrial(url, query);
  await browser.begin(id);
  const browserStateStart = await browser.snapshotState?.();
  await browser.run();
  const finished = await browser.waitStable(id, 180000);
  const browserStateEnd = await browser.snapshotState?.();
  const start = { queryStartedAt: finished.queryStartedAt };
  if (!finished.jobs.length) throw new Error(id + ': no worker layout result observed.');
  const main = finished.jobs.find(job => !job.options?.repairOnly) || finished.jobs.at(-1);
  if (main.error) throw new Error(id + ': worker error ' + main.error);
  if (finished.visibleNodes !== main.graph.nodes.length || main.output.positions.length !== main.graph.nodes.length) {
    throw new Error(id + ': visible/layout/position node counts differ.');
  }
  const jobs = finished.jobs.map(job => ({
    requestId: job.requestId, workerId: job.workerId, sentAt: job.sentAt, receivedAt: job.receivedAt,
    workerRoundTripMs: job.receivedAt - job.sentAt, options: job.options,
    graph: job.graph, output: job.output, error: job.error, initialPositions: job.initialPositions,
    initialPositionBits: job.initialPositionBits, observerSnapshotMs: job.observerSnapshotMs,
  }));
  const priorTransitionCount = browserStateStart?.visibilityFocusTransitions?.length || 0;
  const visibilityFocusTransitions = browserStateEnd?.visibilityFocusTransitions?.slice(priorTransitionCount) || [];
  const environmentIssues = [];
  const focusStates = [];
  for (const [boundary, state] of [['start', browserStateStart], ...visibilityFocusTransitions.map(event => [event.event, event]), ['end', browserStateEnd]]) {
    if (!state) { environmentIssues.push(boundary + ': state unavailable'); continue; }
    if (state.visibility !== 'visible') environmentIssues.push(boundary + ': visibility=' + state.visibility);
    if (typeof state.hasFocus !== 'boolean') environmentIssues.push(boundary + ': hasFocus unavailable');
    else focusStates.push(state.hasFocus);
  }
  if (new Set(focusStates).size > 1) environmentIssues.push('hasFocus changed during trial');
  const sample = {
    id, queryStartedAt: start.queryStartedAt, settledAt: finished.settledAt,
    queryToDispatchMs: jobs[0].sentAt - start.queryStartedAt,
    workerRoundTripMs: jobs.reduce((sum, job) => sum + job.workerRoundTripMs, 0),
    workerSpanMs: Math.max(...jobs.map(job => job.receivedAt)) - Math.min(...jobs.map(job => job.sentAt)),
    replyToVisibleMs: finished.settledAt - Math.max(...jobs.map(job => job.receivedAt)),
    queryToVisibleMs: finished.settledAt - start.queryStartedAt,
    visibleNodes: finished.visibleNodes, visibleEdges: finished.visibleEdges ?? null, renderer: finished.renderer,
    observerSnapshotMs: jobs.reduce((sum, job) => sum + job.observerSnapshotMs, 0), jobs,
    browserStateStart, browserStateEnd, visibilityFocusTransitions,
    environmentValid: environmentIssues.length === 0, environmentIssues,
    primaryJob: jobs.find(job => job.requestId === main.requestId),
  };
  writeFileSync(path.join(outputDir, id + '.json'), JSON.stringify(sample, null, 2) + '\n');
  writeFileSync(path.join(outputDir, id + '.layout-output.json'), JSON.stringify(sample.primaryJob.output, null, 2) + '\n');
  return sample;
}

function installLayoutObserver({diagnose}) {
  window.__pageDiagnostics = [];
  const s = window.__layoutBench = {
    current: null, start: null, workerInstances: 0, dispatches: [], completed: [], pending: new Map(),
    settled: {}, rafCount: 0, lastRafAt: null, visibilityFocusTransitions: [], lastVisibleState: null,
  };
  s.recordVisibilityFocus = event => {
    s.visibilityFocusTransitions.push({event, at: performance.now(), visibility: document.visibilityState,
      hidden: document.hidden, hasFocus: document.hasFocus()});
  };
  s.recordVisibilityFocus('initial');
  s.snapshot = () => {
    const canvas = document.querySelector('.large-graph-interactive');
    return {
      at: performance.now(), trialId: s.current, visibility: document.visibilityState,
      hidden: document.hidden, hasFocus: document.hasFocus(), rafCount: s.rafCount, lastRafAt: s.lastRafAt,
      moving: document.querySelector('.canvas-wrap')?.hasAttribute('data-moving') ?? null,
      visibleNodes: document.querySelectorAll('.graph-node[data-node-id]').length,
      canvas: canvas ? {label: canvas.getAttribute('aria-label'), frames: canvas.dataset.frames} : null,
      renderer: canvas?.dataset.renderer || (document.querySelector('.webgl-layer.is-active') ? 'svg+webgl' : 'svg'),
      dispatches: s.dispatches.map(j => ({requestId: j.requestId, workerId: j.workerId, trialId: j.trialId, sentAt: j.sentAt})),
      completions: s.completed.map(j => ({requestId: j.requestId, receivedAt: j.receivedAt, error: j.error})),
      pending: [...s.pending.keys()], errors: window.__pageDiagnostics.slice(),
      visibilityFocusTransitions: s.visibilityFocusTransitions.slice(), lastVisibleState: s.lastVisibleState,
    };
  };
  s.environmentSnapshot = () => ({
    at: performance.now(), trialId: s.current, visibility: document.visibilityState, hidden: document.hidden,
    hasFocus: document.hasFocus(), rafCount: s.rafCount, lastRafAt: s.lastRafAt,
    moving: document.querySelector('.canvas-wrap')?.hasAttribute('data-moving') ?? null,
    visible: s.lastVisibleState,
    dispatches: s.dispatches.filter(job => job.trialId === s.current)
      .map(job => ({requestId: job.requestId, workerId: job.workerId, sentAt: job.sentAt})),
    completions: s.completed.filter(job => job.trialId === s.current)
      .map(job => ({requestId: job.requestId, receivedAt: job.receivedAt, error: job.error})),
    pending: [...s.pending].filter(([, job]) => job.trialId === s.current).map(([requestId]) => requestId),
    visibilityFocusTransitions: s.visibilityFocusTransitions.slice(),
  });
  s.publish = kind => {
    if (!diagnose) return;
    fetch('/__layout-bench/event', {
      method: 'POST', headers: {'content-type': 'application/json'},
      body: JSON.stringify({kind, state: s.snapshot()}),
    }).catch(error => window.__pageDiagnostics.push('telemetry: ' + error));
  };
  addEventListener('error', event => {
    window.__pageDiagnostics.push('error: ' + event.message + ' ' + event.filename + ':' + event.lineno);
    s.publish('error');
  }, true);
  addEventListener('unhandledrejection', event => {
    window.__pageDiagnostics.push('unhandled: ' + (event.reason?.stack || event.reason));
    s.publish('unhandledrejection');
  }, true);
  for (const type of ['visibilitychange', 'focus', 'blur']) addEventListener(type, () => {
    s.recordVisibilityFocus(type);
    s.publish(type);
  });
  const Native = window.Worker;
  if (!Native) return;
  window.Worker = class extends Native {
    constructor(...args) {
      super(...args);
      this.__layoutBenchWorkerId = ++s.workerInstances;
      this.addEventListener('error', event => {
        window.__pageDiagnostics.push('worker error: ' + event.message);
        s.publish('worker-error');
      });
      this.addEventListener('message', event => {
        const j = event.data && s.pending.get(event.data.requestId);
        if (j && (event.data.result || event.data.error)) {
          j.receivedAt = performance.now();
          j.result = event.data.result || null; j.error = event.data.error || null;
          s.completed.push(j); s.pending.delete(event.data.requestId);
          s.publish('completion');
        }
      });
    }
    postMessage(message, ...transfer) {
      if (message && Number.isInteger(message.requestId) && Array.isArray(message.graph?.nodes)) {
        const snapshotStartedAt = performance.now();
        const graph = message.graph;
        const j = {
          requestId: message.requestId, trialId: s.current, workerId: this.__layoutBenchWorkerId,
          graph: {revision: graph.revision, nodes: graph.nodes.map(node => ({...node})),
            edges: graph.edges.map(edge => ({...edge})),
            ...(graph.statementLinks ? {statementLinks: graph.statementLinks.map(link => ({...link}))} : {})},
          options: structuredClone(message.options || {}),
          initialPositions: graph.nodes.map(node => [node.id, Object.hasOwn(node, 'x'), node.x, Object.hasOwn(node, 'y'), node.y]),
          observerSnapshotMs: 0,
        };
        s.dispatches.push(j); s.pending.set(message.requestId, j);
        j.observerSnapshotMs = performance.now() - snapshotStartedAt;
        j.sentAt = performance.now();
      }
      const result = super.postMessage(message, ...transfer);
      s.publish('dispatch');
      return result;
    }
  };
}

async function startServer({ compiled, webapp, identity, inputResults, labelResults, typeResults, emptyResults, theme, showValues, diagnose, requests, requestStats }) {
  const events = [], waiters = new Map();
  const script = '(' + installLayoutObserver.toString() + ')(' + JSON.stringify({diagnose}) + ');';
  const mime = { '.js':'application/javascript','.mjs':'application/javascript','.css':'text/css','.svg':'image/svg+xml','.json':'application/json','.wasm':'application/wasm','.woff2':'font/woff2','.woff':'font/woff','.map':'application/json' };
  const server = createServer(async (req, res) => {
    const url = new URL(req.url, 'http://127.0.0.1');
    res.setHeader('X-Workbench-Server-Identity', identity);
    res.setHeader('Cache-Control', 'no-store');
    if (url.pathname === '/__layout-bench/event' && req.method === 'POST') {
      let body = ''; for await (const chunk of req) body += chunk;
      const event = {...JSON.parse(body), receivedAtNode: Date.now()};
      events.push(event);
      appendFileSync(path.join(out, 'browser-events.jsonl'), JSON.stringify(event) + '\n');
      const waiter = waiters.get(event.token);
      if (waiter) { waiters.delete(event.token); clearTimeout(waiter.timer); waiter.resolve(event); }
      res.statusCode = 204; res.end(); return;
    }
    if (url.pathname === '/__layout-bench/control') {
      res.setHeader('Content-Type', 'text/html; charset=utf-8');
      res.end('<!doctype html><title>Safari liveness control</title><body>Empty-page control<script>' + script + '</script>');
      return;
    }
    if (url.pathname === '/favicon.ico') { res.statusCode = 204; res.end(); return; }
    if (url.pathname === '/graph') {
      res.setHeader('Content-Type', 'text/html; charset=utf-8');
      res.end(`<!doctype html><html lang="en" data-theme="${theme}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Graph layout benchmark</title><link rel="stylesheet" href="/workbench/styles/workbench-refresh.css"></head><body style="margin:0"><div id="workbench-app" data-workbench-base-path="/workbench" data-workbench-view="graph"><div id="workbench-page-surface" class="workbench-page-surface"><div id="outlet" class="graph-explorer-mount"><div data-graph-explorer-mount></div></div></div></div><script>${script}</script><script>localStorage.clear();localStorage.setItem("graph-field-show-values-v1",${JSON.stringify(String(showValues))});</script><script type="module">import "/workbench/scripts/graph-explorer/graph-explorer.mjs";window.workbench.graphExplorer.mount(document.getElementById("outlet"),{context:{basePath:"/workbench",repositoryId:"layout-benchmark",serverIdentity:${JSON.stringify(identity)}}});</script></body></html>`);
      return;
    }
    if (url.pathname === '/workbench/repositories/layout-benchmark/graph' && req.method === 'POST') {
      let body = ''; for await (const chunk of req) body += chunk;
      const primaryQuery = /SELECT\s+\?source\s+\?predicate\s+\?target\s+WHERE\s*\{\s*\?source\s+\?predicate\s+\?target\s*\}/i.test(body);
      const labelQuery = /SELECT\s+DISTINCT\s+\?resource\s+\?labelProperty\s+\?label/i.test(body);
      const typeQuery = /SELECT\s+\?node\s+\?type/i.test(body);
      const kind = primaryQuery ? 'primary' : labelQuery ? 'labels' : typeQuery ? 'types' : 'other';
      const queryCount = requestStats.get(kind) || { count: 0, responseBindings: 0 };
      queryCount.count++;
      const requestedResources = (body.match(/VALUES\s+\?resource\s*\{([^}]*)\}/is)?.[1] || '')
        .match(/<([^>]+)>/g)?.map(token => token.slice(1, -1));
      const requestedNodes = (body.match(/VALUES\s+\?node\s*\{([^}]*)\}/is)?.[1] || '')
        .match(/<([^>]+)>/g)?.map(token => token.slice(1, -1));
      const selectedLabels = requestedResources?.length
        ? { ...labelResults, results: { bindings: labelResults.results.bindings.filter(row => requestedResources.includes(row.resource.value)) } }
        : labelResults;
      const selectedTypes = requestedNodes?.length
        ? { ...typeResults, results: { bindings: typeResults.results.bindings.filter(row => requestedNodes.includes(row.node.value)) } }
        : typeResults;
      const result = primaryQuery ? inputResults : labelQuery ? selectedLabels : typeQuery ? selectedTypes : emptyResults;
      queryCount.responseBindings += result.results.bindings.length;
      requestStats.set(kind, queryCount);
      if (requests.length < 30 || primaryQuery) requests.push({ kind, queryBytes: Buffer.byteLength(body), querySha256: sha256(body), hasLimit: /\bLIMIT\b/i.test(body), responseBindings: result.results.bindings.length });
      res.setHeader('Content-Type', 'application/sparql-results+json; charset=utf-8');
      res.end(JSON.stringify(result));
      return;
    }
    if (url.pathname.startsWith('/workbench/')) {
      const relative = decodeURIComponent(url.pathname.slice('/workbench/'.length));
      for (const root of [compiled, webapp]) {
        const file = path.resolve(root, relative);
        if (file.startsWith(root + path.sep) && existsSync(file)) {
          res.setHeader('Content-Type', mime[path.extname(file)] || 'application/octet-stream');
          createReadStream(file).pipe(res);
          return;
        }
      }
    }
    res.statusCode = 404; res.end('Not found: ' + url.pathname);
  });
  await new Promise((resolve, reject) => { server.once('error', reject); server.listen(0,'127.0.0.1',resolve); });
  return {
    server, events, origin:'http://127.0.0.1:' + server.address().port,
    waitForEvent(token, timeoutMs) {
      const received = events.find(event => event.token === token);
      if (received) return Promise.resolve(received);
      return new Promise((resolve, reject) => {
        const timer = setTimeout(() => {
          waiters.delete(token);
          reject(new Error('Browser result watchdog expired: ' + token + '; telemetry=' + JSON.stringify(events)));
        }, timeoutMs);
        waiters.set(token, {resolve, timer});
      });
    },
  };
}

async function playwrightAdapter(name, viewport, theme) {
  const { chromium, webkit } = await import('playwright');
  const type = name === 'chrome' ? chromium : webkit;
  const browser = await type.launch({ channel:name === 'chrome' ? 'chrome' : undefined, headless:false });
  const context = await browser.newContext({ viewport, deviceScaleFactor:1, colorScheme:theme });
  const page = await context.newPage();
  const diagnostics = [];
  page.on('console', message => { if (message.type() === 'error') diagnostics.push('console: ' + message.text()); });
  page.on('pageerror', error => diagnostics.push('pageerror: ' + error.name + ': ' + error.message + ' ' + error.stack));
  page.on('requestfailed', request => diagnostics.push('request failed: ' + request.url() + ' ' + request.failure()?.errorText));
  page.on('response', response => { if (response.status() >= 400) diagnostics.push('HTTP ' + response.status() + ' ' + response.url()); });
  return {
    async snapshotState() { return page.evaluate(() => window.__layoutBench?.environmentSnapshot()); },
    async metadata() {
      const details = await page.evaluate(() => ({ userAgent:navigator.userAgent, platform:navigator.platform, devicePixelRatio, innerWidth, innerHeight, webgl:(()=>{const c=document.createElement('canvas');const gl=c.getContext('webgl2')||c.getContext('webgl');return gl?gl.getParameter(gl.VERSION):null})() }));
      return { browserName:name === 'chrome' ? 'installed Chrome channel' : 'Playwright WebKit', browserVersion:browser.version(), ...details };
    },
    async open(url) { await page.goto(url,{waitUntil:'domcontentloaded'}); },
    async resetForTrial(_url, query) {
      const hasGraph = await page.evaluate(() => Boolean(document.querySelector('.large-graph-interactive') || document.querySelector('.graph-node[data-node-id]')));
      if (hasGraph) {
        await page.locator('summary[aria-label="Open workspace tools"]').click();
        await page.getByRole('button',{name:'Clear graph'}).click();
        await page.waitForFunction(() => !document.querySelector('.large-graph-interactive') && document.querySelectorAll('.graph-node[data-node-id]').length === 0 && window.__layoutBench.pending.size === 0, null, {timeout:30000});
      }
      await this.prepareQuery(query);
    },
    async setViewport(size) { await page.setViewportSize(size); },
    async waitReady() {
      try {
        await page.locator('#graph-explorer-app').waitFor({state:'visible',timeout:30000});
        await page.getByRole('button',{name:'Query editor'}).first().waitFor({state:'visible',timeout:30000});
      } catch (error) {
        const state = await page.evaluate(() => ({ href:location.href, body:document.body.innerText, html:document.body.innerHTML.slice(0,6000), scripts:[...document.scripts].map(s=>({src:s.src,type:s.type})), resources:performance.getEntriesByType('resource').map(e=>e.name), pageDiagnostics:window.__pageDiagnostics, root:document.querySelector('#workbench-outlet')?.innerHTML.slice(0,3000) }));
        const report = {state,diagnostics};
        writeFileSync(path.join(out, 'browser-readiness-debug.json'), JSON.stringify(report, null, 2) + '\n');
        throw new Error(error.message + '\nDiagnostics saved to ' + path.join(out, 'browser-readiness-debug.json'));
      }
    },
    async prepareQuery(query) {
      const toggle = page.getByRole('button',{name:'Query editor'}).first();
      if (await toggle.getAttribute('aria-expanded') !== 'true') await toggle.click();
      await page.locator('#sparql').fill(query);
      if (await toggle.getAttribute('aria-expanded') === 'true') await page.getByRole('button',{name:'Close query workspace'}).click();
    },
    async begin(id) {
      await page.evaluate(id => { const s=window.__layoutBench;s.current=id;s.start=null;s.lastVisibleState=null; },id);
    },
    async run() {
      await page.locator('#query-workspace .query-actions button').first().evaluate(button => {
        window.__layoutBench.start=performance.now();button.click();
      });
    },
    async waitStable(id,timeout) {
      const rendered=await withWatchdog(page.evaluate(waitStableView,{trialId:id,timeoutMs:timeout}),timeout,'Chrome visible settlement');
      return page.evaluate(({id,serializer,rendered})=>{const build=(0,eval)('('+serializer+')');return build(window.__layoutBench,id,rendered)},{id,serializer:serializeTrial.toString(),rendered});
    },
    async captureViews(directory, targets) {
      const paths=[];
      await page.getByRole('button',{name:'Fit graph to view'}).click();
      await waitViewStable(page);
      paths.push(await screenshot(page,directory,'fit'));
      if(await page.locator('.large-graph-interactive').count()){
        for(let i=0;i<3;i++)await page.getByRole('button',{name:'Zoom in'}).click();
        await waitViewStable(page);
        paths.push({...await screenshot(page,directory,'canvas-zoom'),note:'Canvas view: fit and viewport zoom captured; no SVG node target is claimed.'});
        return paths;
      }
      for(const kind of ['dense','leaf','label']){
        await page.getByRole('button',{name:'Fit graph to view'}).click();
        await waitViewStable(page);
        const index=await page.locator('.graph-node[data-node-id]').evaluateAll((nodes,id)=>nodes.findIndex(node=>node.getAttribute('data-node-id')===id),targets[kind].id);
        if(index<0)throw new Error('The '+kind+' screenshot target is not rendered: '+targets[kind].id);
        await page.locator('.graph-node[data-node-id]').nth(index).click();
        await page.getByRole('button',{name:'Zoom in'}).click({clickCount:3});
        await waitViewStable(page);
        paths.push({...await screenshot(page,directory,kind),nodeId:targets[kind].id,degree:targets[kind].degree});
        const close=page.locator('button[aria-label="Close details"]');
        if(await close.count())await close.click();
      }
      return paths;
    },
    async profileTrial() {
      if(name!=='chrome')return {kind:'Playwright WebKit',note:'No CDP CPU profile is available; this is not native Safari.'};
      const session=await context.newCDPSession(page),workers=await profileLayoutWorkers(browser);
      try{
        await session.send('Profiler.enable');await session.send('Profiler.start');
        await this.begin('profile-1');await this.run();await this.waitStable('profile-1',180000);
        const result=await session.send('Profiler.stop');
        return {kind:'Chrome DevTools V8 profiles, separate from timing samples',page:result.profile,workers:await workers.stop()};
      }finally{await workers.close();await session.detach();}
    },
    async failureEvidence(directory) {
      try {
        const state=await withWatchdog(page.evaluate(()=>window.__layoutBench?.snapshot()),5000,'Chrome failure state');
        writeFileSync(path.join(directory,'browser-failure-state.json'),JSON.stringify(state,null,2)+'\n');
        await withWatchdog(page.screenshot({path:path.join(directory,'screenshot-failure.png')}),5000,'Chrome failure screenshot');
      } catch(error) { writeFileSync(path.join(directory,'failure-capture-error.txt'),String(error)+'\n'); }
    },
    async close(){await context.close().catch(()=>{});await browser.close().catch(()=>{});}
  };
}

async function safariAdapter(viewport, server, options = {}) {
  const reuseSession=Boolean(options['safari-session-id']);
  const idleUrl=options['safari-idle-url'];
  const port=reuseSession?null:await freePort();
  const proc=reuseSession?null:spawn('/usr/bin/safaridriver',['--port',String(port)],{stdio:['ignore','pipe','pipe']});
  let logs='';proc?.stdout.on('data',d=>logs+=d);proc?.stderr.on('data',d=>logs+=d);
  const origin=reuseSession?options['safari-driver-origin']:'http://127.0.0.1:'+port;
  let id=reuseSession?options['safari-session-id']:undefined, created=null;
  try {
    if(!reuseSession){
      await pollJson(origin+'/status',30000);
      created=await wd(origin,'POST','/session',{capabilities:{alwaysMatch:{browserName:'Safari',platformName:'macOS','safari:automaticProfiling':false}}});
      id=created.value?.sessionId??created.sessionId;if(!id)throw new Error(JSON.stringify(created));
    }else{
      const base='/session/'+id;
      const state=(await wd(origin,'POST',base+'/execute/sync',{script:'return {title:document.title,href:location.href,visibility:document.visibilityState,hasFocus:document.hasFocus(),innerWidth,innerHeight}',args:[]},5000)).value;
      if(state.href!==idleUrl)throw new Error('The reused Safari window is not on its approved idle URL: '+JSON.stringify(state));
      if(state.visibility!=='visible')throw new Error('The reused Safari session is not visible: '+JSON.stringify(state));
      if(state.innerWidth!==viewport.width||state.innerHeight!==viewport.height)throw new Error('The reused Safari viewport must already match '+viewport.width+'x'+viewport.height+'; preserving the user-set window: '+JSON.stringify(state));
    }
    const base='/session/'+id;
    let resultSequence=0;
    const adapter={
      async execute(script,args=[]){
        return (await wd(origin,'POST',base+'/execute/sync',{script,args})).value;
      },
      async snapshotState(){ return this.execute('return window.__layoutBench?.environmentSnapshot()'); },
      async background(expression,timeoutMs){
        const token='safari-result-'+(++resultSequence),started=Date.now();
        // Return the synchronous WebDriver command before waiting for the page's Promise. In particular,
        // an outstanding async inspector command must not gate Safari's rendering/event-loop progress.
        const send="event=>fetch('/__layout-bench/event',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({token:"+JSON.stringify(token)+",...event})})";
        await this.execute('Promise.resolve().then(()=>('+expression+')).then(value=>('+send+')({ok:true,value}),error=>('+send+')({ok:false,error:String(error.stack||error),state:window.__layoutBench?.snapshot()})).catch(error=>window.__pageDiagnostics?.push("result transport: "+error));return true');
        const event=await server.waitForEvent(token,Math.max(0,timeoutMs-(Date.now()-started)));
        if(!event.ok)throw new Error('Safari background script failed: '+event.error+'; state='+JSON.stringify(event.state));
        return event.value;
      },
      async livenessControl(originUrl){
        await wd(origin,'POST',base+'/url',{url:originUrl+'/__layout-bench/control'});
        const control={before:await this.execute('return window.__layoutBench.snapshot()')};
        const save=()=>writeFileSync(path.join(out,'safari-liveness-control.json'),JSON.stringify(control,null,2)+'\n');
        save();
        if(control.before.hidden){
          const handle=(await wd(origin,'GET',base+'/window')).value;
          await wd(origin,'POST',base+'/window',{handle});
          control.afterWindowSwitch=await this.execute('return window.__layoutBench.snapshot()');
          save();
        }
        await wd(origin,'POST',base+'/timeouts',{script:5000});
        for(const [name,script] of [
          ['asyncMicrotask','const done=arguments[arguments.length-1];Promise.resolve().then(()=>done({at:performance.now(),visibility:document.visibilityState,hasFocus:document.hasFocus()}));'],
          ['asyncRafVsTimer',"const done=arguments[arguments.length-1];let timer=0,raf=0,finished=false;const finish=(winner,at)=>{if(finished)return;finished=true;clearTimeout(timer);cancelAnimationFrame(raf);done({winner,at,visibility:document.visibilityState,hasFocus:document.hasFocus()})};raf=requestAnimationFrame(at=>finish('raf',at));timer=setTimeout(()=>finish('timer',performance.now()),1000);"],
        ]){
          try{control[name]=(await wd(origin,'POST',base+'/execute/async',{script,args:[]},10000)).value;}
          catch(error){control[name]={error:String(error)};save();if(error.name==='TimeoutError')throw error;}
          save();
        }
        // This control uses exactly the same detached-result transport as graph settlement, without any graph.
        control.detachedRafVsTimer=await this.background('new Promise(resolve=>{let timer=0,raf=0,finished=false;const finish=(winner,at)=>{if(finished)return;finished=true;clearTimeout(timer);cancelAnimationFrame(raf);resolve({winner,at,visibility:document.visibilityState,hasFocus:document.hasFocus()})};raf=requestAnimationFrame(at=>finish("raf",at));timer=setTimeout(()=>finish("timer",performance.now()),1000)})',5000);
        control.after=await this.execute('return window.__layoutBench.snapshot()');
        await wd(origin,'POST',base+'/timeouts',{script:180000});
        return control;
      },
      async open(url){await wd(origin,'POST',base+'/url',{url});await this.waitReady();},
      async resetForTrial(_url,query){
        const hasGraph=await this.execute("return Boolean(document.querySelector('.large-graph-interactive')||document.querySelector('.graph-node[data-node-id]'))");
        if(hasGraph){
          await this.execute("document.querySelector('summary[aria-label=\"Open workspace tools\"]').click();return true");
          await this.execute("[...document.querySelectorAll('.toolbar-menu-popover button')].find(button=>button.textContent.trim()==='Clear graph').click();return true");
          await this.waitFor("!document.querySelector('.large-graph-interactive')&&!document.querySelector('.graph-node[data-node-id]')&&window.__layoutBench.pending.size===0",30000);
        }
        const open=await this.execute("return document.querySelector('button[aria-label=\"Query editor\"]')?.getAttribute('aria-expanded')==='true'");
        if(!open)await this.execute("document.querySelector('button[aria-label=\"Query editor\"]').click();return true");
        await this.execute("const e=document.querySelector('#sparql');Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(e,"+JSON.stringify(query)+");e.dispatchEvent(new Event('input',{bubbles:true}));return true");
        await this.execute("if(document.querySelector('button[aria-label=\"Query editor\"]')?.getAttribute('aria-expanded')==='true')document.querySelector('button[aria-label=\"Close query workspace\"]').click();return true");
      },
      async setViewport(size){
        if(reuseSession){
          const current=await this.execute('return {width:innerWidth,height:innerHeight}');
          if(current.width!==size.width||current.height!==size.height)throw new Error('Preserving the user-set native Safari viewport; expected '+size.width+'x'+size.height+', observed '+current.width+'x'+current.height);
          return;
        }
        const original=(await wd(origin,'GET',base+'/window/rect')).value;
        await wd(origin,'POST',base+'/window/rect',{x:original.x,y:original.y,width:size.width,height:size.height+140});
        for(let i=0;i<4;i++){const s=await this.execute('return {width:innerWidth,height:innerHeight}');if(s.width===size.width&&s.height===size.height)return;const r=(await wd(origin,'GET',base+'/window/rect')).value;await wd(origin,'POST',base+'/window/rect',{x:r.x,y:r.y,width:r.width+size.width-s.width,height:r.height+size.height-s.height});}
      },
      async waitReady(){
        await this.waitFor("document.querySelector('#graph-explorer-app')&&document.querySelector('button[aria-label=\"Query editor\"]')",30000);
      },
      async waitFor(expression,timeout){
        const start=Date.now();
        while(Date.now()-start<timeout){
          if(await this.execute('return Boolean('+expression+')'))return;
          await new Promise(r=>setTimeout(r,60));
        }
        throw new Error('Safari WebDriver wait timed out. '+logs);
      },
      async prepareQuery(query){
        await this.execute("document.querySelector('button[aria-label=\"Query editor\"]').click();return true");
        const setter="const e=document.querySelector('#sparql');Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(e,"+JSON.stringify(query)+");e.dispatchEvent(new Event('input',{bubbles:true}));return true";
        await this.execute(setter);
        await this.execute("document.querySelector('button[aria-label=\"Close query workspace\"]').click();return true");
      },
      async begin(trial){
        await this.execute('const s=window.__layoutBench;s.current='+JSON.stringify(trial)+';s.start=null;s.lastVisibleState=null;return true');
      },
      async run(){await this.execute("window.__layoutBench.start=performance.now();document.querySelector('#query-workspace .query-actions button').click();return true");},
      async waitStable(trial,timeout){
        const id=JSON.stringify(trial);
        const rendered=await this.background('('+waitStableView.toString()+')({trialId:'+id+',timeoutMs:'+timeout+'})',timeout);
        return this.execute('return ('+serializeTrial.toString()+')(window.__layoutBench,'+id+','+JSON.stringify(rendered)+')');
      },
      async captureViews(directory,targets){
        await this.execute("document.querySelector('button[aria-label=\"Fit graph to view\"]').click();return true");
        await safariWaitStable(this);
        const rows=[await shot(this,directory,'fit',origin,base)];
        if(await this.execute("return Boolean(document.querySelector('.large-graph-interactive'))")){
          await this.execute("for(let i=0;i<3;i++)document.querySelector('button[aria-label=\"Zoom in\"]').click();return true");
          await safariWaitStable(this);
          rows.push({...await shot(this,directory,'canvas-zoom',origin,base),note:'Canvas view: fit and viewport zoom captured; no SVG node target is claimed.'});
          return rows;
        }
        for(const kind of ['dense','leaf','label']){
          await this.execute("document.querySelector('button[aria-label=\"Fit graph to view\"]').click();return true");
          await safariWaitStable(this);
          const index=await this.execute("return [...document.querySelectorAll('.graph-node[data-node-id]')].findIndex(node=>node.getAttribute('data-node-id')==="+JSON.stringify(targets[kind].id)+")");
          if(index<0)throw new Error('The '+kind+' screenshot target is not rendered: '+targets[kind].id);
          await this.execute("document.querySelectorAll('.graph-node[data-node-id]')["+index+"].click();for(let i=0;i<3;i++)document.querySelector('button[aria-label=\"Zoom in\"]').click();return true");
          await safariWaitStable(this);
          rows.push({...await shot(this,directory,kind,origin,base),nodeId:targets[kind].id,degree:targets[kind].degree});
          if(await this.execute("return document.querySelector('button[aria-label=\"Close details\"]')!==null"))
            await this.execute("document.querySelector('button[aria-label=\"Close details\"]').click();return true");
        }
        return rows;
      },
      async profileTrial(){return {kind:'native Safari not profiled in the timing session',note:'Safari native timings and Worker round trips are recorded; no automatic Web Inspector timeline export is claimed.'};},
      async metadata(){const d=await this.execute("return {userAgent:navigator.userAgent,platform:navigator.platform,devicePixelRatio,innerWidth,innerHeight,webgl:(()=>{const c=document.createElement('canvas');const g=c.getContext('webgl2')||c.getContext('webgl');return g?g.getParameter(g.VERSION):null})()}");return {browserName:'Safari native WebDriver',browserVersion:created?.value?.capabilities?.browserVersion||options['safari-browser-version']||'unknown',platformName:created?.value?.capabilities?.platformName||'macOS',platformVersion:created?.value?.capabilities?.['safari:platformVersion']||options['safari-platform-version']||'unknown',...d};},
      async failureEvidence(directory){
        try{
          const state=(await wd(origin,'POST',base+'/execute/sync',{script:'return window.__layoutBench?.snapshot()',args:[]},5000)).value;
          writeFileSync(path.join(directory,'browser-failure-state.json'),JSON.stringify(state,null,2)+'\n');
        }catch(error){writeFileSync(path.join(directory,'failure-state-error.txt'),String(error)+'\n');}
        try{
          const image=(await wd(origin,'GET',base+'/screenshot',undefined,5000)).value;
          writeFileSync(path.join(directory,'screenshot-failure.png'),Buffer.from(image,'base64'));
        }catch(error){writeFileSync(path.join(directory,'failure-screenshot-error.txt'),String(error)+'\n');}
      },
      async close(){
        if(reuseSession){
          try{await wd(origin,'POST',base+'/url',{url:idleUrl},5000);}
          catch(error){writeFileSync(path.join(out,'browser-idle-return-error.txt'),String(error)+'\n');throw error;}
          return;
        }
        try{await wd(origin,'DELETE',base,undefined,5000);}finally{proc.kill('SIGTERM');}
      }
    };
    if(!reuseSession)await wd(origin,'POST',base+'/timeouts',{implicit:0,pageLoad:120000,script:180000});
    await adapter.setViewport(viewport);
    return adapter;
  }catch(error){if(!reuseSession)proc.kill('SIGTERM');throw new Error(error.message+'\nSafari WebDriver: '+logs);}
}

// Runs in either browser. Stable canvas frame counters cover the large-graph renderer's own animation;
// SVG positions and the viewport transform cover the small-graph renderer. Verification frames do not
// inflate the reported endpoint: it is the first frame of the subsequently confirmed stable sequence.
async function waitStableView({trialId=null,timeoutMs=120000}={}){
  const s=window.__layoutBench,deadline=performance.now()+timeoutMs;
  let last='',count=0,stableAt=0,view;
  return new Promise((resolve,reject)=>{
    let raf=0,finished=false;
    const finish=(error,result)=>{
      if(finished)return;
      finished=true;clearTimeout(watchdog);cancelAnimationFrame(raf);
      if(error)reject(error);else resolve(result);
    };
    const expired=()=>{
      s.publish?.('visible-settlement-timeout');
      finish(new Error('Graph did not reach stable visible frames: '+JSON.stringify({trialId,view,state:s.snapshot?.(),diagnostics:window.__pageDiagnostics})));
    };
    // rAF can be suspended in a hidden Safari window. A timer can reject, but only real rAF frames can settle.
    const watchdog=setTimeout(expired,timeoutMs);
    const frame=()=>{
      if(finished)return;
      if(performance.now()>=deadline){expired();return;}
      try{
        s.rafCount++;s.lastRafAt=performance.now();
        const jobs=trialId===null?[]:s.completed.filter(j=>j.trialId===trialId);
        const pending=trialId!==null&&s.dispatches.some(j=>j.trialId===trialId&&s.pending.has(j.requestId));
        const wrap=document.querySelector('.canvas-wrap'),canvas=document.querySelector('.large-graph-interactive');
        let signature='',ready=Boolean(wrap)&&!wrap.hasAttribute('data-moving');
        if(canvas){
          const counts=/with (\d+) nodes and (\d+) edges/.exec(canvas.getAttribute('aria-label')||'');
          view={visibleNodes:Number(counts?.[1]||0),visibleEdges:Number(counts?.[2]||0),renderer:canvas.dataset.renderer||'canvas-pending'};
          signature='canvas:'+canvas.dataset.frames+':'+canvas.dataset.uploadedBytes+':'+canvas.getAttribute('aria-label');
          ready&&=Number(canvas.dataset.frames)>0&&document.querySelector('.large-graph-hint')?.getAttribute('aria-busy')!=='true';
        }else{
          const nodes=[...document.querySelectorAll('.graph-node[data-node-id]')],svg=document.querySelector('.graph-canvas');
          view={visibleNodes:nodes.length,renderer:document.querySelector('.webgl-layer.is-active')?'svg+webgl':'svg'};
          signature=(svg?.querySelector(':scope > g[transform]')?.getAttribute('transform')||'')+'|'+nodes.map(n=>n.getAttribute('data-node-id')+'='+n.getAttribute('transform')).join('|');
          ready&&=nodes.length>0;
        }
        if(trialId!==null)ready&&=jobs.length>0&&!pending&&view.visibleNodes===jobs.at(-1).graph.nodes.length;
        if(ready&&signature===last){if(!count)stableAt=performance.now();count++;}else count=0;
        last=signature;
        if(count>=5){if(trialId!==null){s.settled[trialId]=stableAt;s.lastVisibleState={at:stableAt,...view,moving:false};}finish(null,{...view,settledAt:stableAt});return;}
        raf=requestAnimationFrame(frame);
      }catch(error){finish(error);}
    };
    raf=requestAnimationFrame(frame);
  });
}

async function profileLayoutWorkers(browser){
  const connection=await browser.newBrowserCDPSession(),pending=new Map(),attached=[];
  let sequence=0;
  const received=event=>{
    const message=JSON.parse(event.message),key=event.sessionId+':'+message.id,waiter=pending.get(key);
    if(!waiter)return;
    pending.delete(key);clearTimeout(waiter.timer);
    if(message.error)waiter.reject(new Error(waiter.method+': '+JSON.stringify(message.error)));
    else waiter.resolve(message.result);
  };
  connection.on('Target.receivedMessageFromTarget',received);
  const send=(sessionId,method,params={})=>new Promise((resolve,reject)=>{
    const id=++sequence,key=sessionId+':'+id;
    const timer=setTimeout(()=>{pending.delete(key);reject(new Error('Worker CDP command timed out: '+method));},30000);
    pending.set(key,{resolve,reject,timer,method});
    connection.send('Target.sendMessageToTarget',{sessionId,message:JSON.stringify({id,method,params})}).catch(error=>{
      pending.delete(key);clearTimeout(timer);reject(error);
    });
  });
  const close=async()=>{
    for(const target of attached)await connection.send('Target.detachFromTarget',{sessionId:target.sessionId}).catch(()=>{});
    connection.off('Target.receivedMessageFromTarget',received);
    for(const waiter of pending.values()){clearTimeout(waiter.timer);waiter.reject(new Error('Worker profiler closed'));}
    pending.clear();await connection.detach();
  };
  try{
    const {targetInfos}=await connection.send('Target.getTargets');
    const targets=targetInfos.filter(target=>target.type==='worker'&&target.url.includes('graph-layout-worker'));
    if(!targets.length)throw new Error('No graph-layout Worker target to profile: '+JSON.stringify(targetInfos));
    for(const target of targets){
      // Public CDP nested-session routing permits profiling the Worker without private Playwright APIs.
      const {sessionId}=await connection.send('Target.attachToTarget',{targetId:target.targetId,flatten:false});
      attached.push({...target,sessionId});
      await send(sessionId,'Profiler.enable');await send(sessionId,'Profiler.start');
    }
    return {
      async stop(){
        const profiles=[];
        for(const target of attached){
          const {profile}=await send(target.sessionId,'Profiler.stop');
          if(!profile.samples?.length)throw new Error('Layout Worker CPU profile has no samples: '+target.url);
          const resources=await send(target.sessionId,'Runtime.evaluate',{
            expression:'performance.getEntriesByType("resource").map(entry=>({name:entry.name,startTime:entry.startTime,duration:entry.duration}))',returnByValue:true,
          });
          profiles.push({targetId:target.targetId,url:target.url,resources:resources.result?.value,profile});
        }
        return profiles;
      },close,
    };
  }catch(error){await close();throw error;}
}

function serializeTrial(s,id,rendered){
  // JSON preserves finite double precision, but normalizes -0. Retain the raw IEEE-754 bytes as well.
  const numericBits=value=>{
    const view=new DataView(new ArrayBuffer(8)),parts=[];
    const visit=item=>{
      if(typeof item==='number'){
        if(!Number.isFinite(item))throw new Error('Non-finite layout output');
        view.setFloat64(0,item,true);
        for(let i=0;i<8;i++)parts.push(view.getUint8(i).toString(16).padStart(2,'0'));
      }else if(Array.isArray(item))item.forEach(visit);
      else if(item&&typeof item==='object')Object.keys(item).sort().forEach(key=>visit(item[key]));
    };
    visit(value);return parts.join('');
  };
  const optionsValue=value=>value instanceof Set?[...value]:value instanceof Map?[...value]:Array.isArray(value)?value.map(optionsValue):value&&typeof value==='object'?Object.fromEntries(Object.entries(value).map(([key,item])=>[key,optionsValue(item)])):value;
  const jobs=s.completed.filter(j=>j.trialId===id).map(j=>{
    const r=j.result||{};
    const positions=[...(r.positions||new Map())].sort(([a],[b])=>a.localeCompare(b));
    const bends=[...(r.bends||new Map())].sort(([a],[b])=>a.localeCompare(b));
    const routes=[...(r.routes||new Map())].sort(([a],[b])=>a.localeCompare(b));
    return {requestId:j.requestId,trialId:j.trialId,workerId:j.workerId,sentAt:j.sentAt,receivedAt:j.receivedAt,options:optionsValue(j.options),observerSnapshotMs:j.observerSnapshotMs,initialPositions:j.initialPositions,
      initialPositionBits:numericBits(j.initialPositions),
      graph:{revision:j.graph.revision,nodes:j.graph.nodes.map(n=>({...n})),edges:j.graph.edges.map(e=>({...e})),...(j.graph.statementLinks?{statementLinks:j.graph.statementLinks.map(x=>({...x}))}:{})},
      output:{nodeOrder:j.graph.nodes.map(n=>n.id),positions,bends,routes,numericBits:{positions:numericBits(positions),bends:numericBits(bends),routes:numericBits(routes)},fixedOverlaps:r.fixedOverlaps??null,grouped:r.grouped??false,fanned:r.fanned??false},error:j.error};
  });
  return {id,queryStartedAt:s.start,...rendered,jobs};
}

function chooseViewTargets(graph, rows) {
  const degree = new Map(graph.nodes.map(node => [node.id, 0]));
  for (const edge of graph.edges) {
    degree.set(edge.source, (degree.get(edge.source) || 0) + 1);
    degree.set(edge.target, (degree.get(edge.target) || 0) + 1);
  }
  const byDegree = [...graph.nodes].sort((a,b) =>
    (degree.get(b.id) - degree.get(a.id)) || a.id.localeCompare(b.id));
  const dense = byDegree[0];
  const leaf = byDegree.filter(node => degree.get(node.id) === 1).at(-1) || byDegree.at(-1);
  const labelRow = rows.find(row => row.predicate?.value === 'http://www.w3.org/2000/01/rdf-schema#label'
    && graph.nodes.some(node => node.id === row.source?.value));
  const label = graph.nodes.find(node => node.id === labelRow?.source?.value) || dense;
  return Object.fromEntries([['dense',dense],['leaf',leaf],['label',label]].map(([kind,node]) =>
    [kind,{id:node.id,degree:degree.get(node.id),label:node.label,termValue:node.termValue}]));
}
