function modelSummary(graph,rows){
  const degree=new Map(graph.nodes.map(n=>[n.id,0]));
  for(const e of graph.edges){degree.set(e.source,(degree.get(e.source)||0)+1);degree.set(e.target,(degree.get(e.target)||0)+1);}
  return {inputRows:rows.length,layoutNodes:graph.nodes.length,layoutEdges:graph.edges.length,distinctPredicates:new Set(rows.map(r=>r.predicate.value)).size,maxDegree:Math.max(0,...degree.values())};
}
function hashes(out){
  const pos=JSON.stringify({nodeOrder:out.nodeOrder,positions:out.positions,bits:out.numericBits?.positions});
  const route=JSON.stringify({nodeOrder:out.nodeOrder,bends:out.bends,routes:out.routes,bits:[out.numericBits?.bends,out.numericBits?.routes]});
  return {positionsSha256:sha256(pos),routesSha256:sha256(route),completeSha256:sha256(JSON.stringify({positions:pos,routes:route}))};
}
function compact(s){
  return {
    id:s.id, queryToDispatchMs:s.queryToDispatchMs, observerSnapshotMs:s.observerSnapshotMs,
    workerRoundTripMs:s.workerRoundTripMs, workerSpanMs:s.workerSpanMs, replyToVisibleMs:s.replyToVisibleMs,
    queryToVisibleMs:s.queryToVisibleMs, visibleNodes:s.visibleNodes, visibleEdges:s.visibleEdges, renderer:s.renderer,
    environmentValid:s.environmentValid, environmentIssues:s.environmentIssues,
    browserStateStart:s.browserStateStart, browserStateEnd:s.browserStateEnd,
    visibilityFocusTransitions:s.visibilityFocusTransitions,
    jobs:s.jobs.map(j=>({requestId:j.requestId,workerId:j.workerId,workerRoundTripMs:j.receivedAt-j.sentAt,
      observerSnapshotMs:j.observerSnapshotMs,options:j.options,nodes:j.graph.nodes.length,edges:j.graph.edges.length,
      outputBends:j.output.bends.length,outputRoutes:j.output.routes.length,
      positionedNodes:j.initialPositions.filter(([,hasX,x,hasY,y])=>(hasX&&Number.isFinite(x))||(hasY&&Number.isFinite(y))).length,
      initialPositionsSha256:sha256(JSON.stringify({positions:j.initialPositions,numericBits:j.initialPositionBits})),
      optionsSha256:sha256(JSON.stringify(canonical(j.options))),graphInputSha256:graphInputHash(j.graph),hashes:hashes(j.output)}))
  };
}
function auditLivenessControl(control){
  const states=[control.before,control.afterWindowSwitch,control.after].filter(Boolean);
  const visible=states.length>=2&&states.every(state=>state.visibility==='visible'&&!state.hidden);
  const boundedResult=result=>Boolean(result&&['raf','timer'].includes(result.winner)&&Number.isFinite(result.at));
  const asyncRace=boundedResult(control.asyncRafVsTimer);
  const detachedRace=boundedResult(control.detachedRafVsTimer);
  const focusStates=states.map(state=>state.hasFocus).filter(value=>typeof value==='boolean');
  return {valid:visible&&asyncRace&&detachedRace,visible,asyncRafTimerCompleted:asyncRace,detachedRafTimerCompleted:detachedRace,focusStates,focusConsistent:new Set(focusStates).size<=1,states};
}
function auditEnvironment(samples){
  const trials=samples.map(sample=>({
    id:sample.id, valid:sample.environmentValid, issues:[...sample.environmentIssues],
    startVisibility:sample.browserStateStart?.visibility??null, endVisibility:sample.browserStateEnd?.visibility??null,
    startHasFocus:typeof sample.browserStateStart?.hasFocus==='boolean'?sample.browserStateStart.hasFocus:null,
    endHasFocus:typeof sample.browserStateEnd?.hasFocus==='boolean'?sample.browserStateEnd.hasFocus:null,
    transitions:sample.visibilityFocusTransitions,
  }));
  const focusStates=trials.flatMap(trial=>[trial.startHasFocus,trial.endHasFocus]).filter(value=>typeof value==='boolean');
  const focusConsistentAcrossTrials=trials.length>0&&focusStates.length===trials.length*2&&new Set(focusStates).size===1;
  const globalIssues=focusConsistentAcrossTrials?[]:['hasFocus was unavailable or changed across compared trials'];
  const invalidTrials=trials.filter(trial=>!trial.valid).map(trial=>({id:trial.id,issues:trial.issues}));
  if(globalIssues.length)for(const trial of trials){
    const existing=invalidTrials.find(row=>row.id===trial.id);
    if(existing)existing.issues.push(...globalIssues);else invalidTrials.push({id:trial.id,issues:[...globalIssues]});
  }
  return {valid:invalidTrials.length===0,focusMode:focusConsistentAcrossTrials?focusStates[0]:null,focusConsistentAcrossTrials,globalIssues,invalidTrials,trials};
}
function auditStarts(samples){
  const starts=samples.map(sample=>{
    const job=sample.primaryJob,positions=job.initialPositions;
    const positionsMatchNodes=positions.length===job.graph.nodes.length&&positions.every((row,index)=>{
      const node=job.graph.nodes[index];
      return row[0]===node.id&&row[1]===true&&row[3]===true&&Number.isFinite(row[2])&&Number.isFinite(row[4])&&Object.is(row[2],node.x)&&Object.is(row[4],node.y);
    });
    return {id:sample.id,nodes:job.graph.nodes.length,edges:job.graph.edges.length,revision:job.graph.revision,positionsMatchNodes,workerId:job.workerId,initialPositionsSha256:sha256(JSON.stringify({positions,numericBits:job.initialPositionBits})),optionsSha256:sha256(JSON.stringify(canonical(job.options))),graphInputSha256:graphInputHash(job.graph)};
  });
  const identical=(key)=>new Set(starts.map(row=>row[key])).size===1;
  const result={allPositionSnapshotsMatchNodes:starts.every(row=>row.positionsMatchNodes),identicalInitialPositions:identical("initialPositionsSha256"),identicalOptions:identical("optionsSha256"),identicalGraphInputs:identical("graphInputSha256"),sameWorker:identical("workerId"),starts};
  if(!result.allPositionSnapshotsMatchNodes||!result.identicalInitialPositions||!result.identicalOptions||!result.identicalGraphInputs||!result.sameWorker)throw new Error("Warmup/repeat inputs are not identical fresh starts on one retained Worker: "+JSON.stringify(result));
  return result;
}
function graphInputHash(graph){
  const nodes=graph.nodes.map(({x,y,...node})=>node);
  const edges=graph.edges.map(({batchId,...edge})=>edge);
  const statementLinks=graph.statementLinks?.map(({batchId,...link})=>link);
  return sha256(JSON.stringify(canonical({nodes,edges,statementLinks})));
}
function canonical(value){
  if(Array.isArray(value))return value.map(canonical);
  if(value&&typeof value==="object")return Object.fromEntries(Object.keys(value).sort().map(key=>[key,canonical(value[key])]));
  return value;
}
function summarize(samples){
  const names=['queryToDispatchMs','observerSnapshotMs','workerRoundTripMs','workerSpanMs','replyToVisibleMs','queryToVisibleMs'];
  return Object.fromEntries(names.map(name=>{const v=samples.map(s=>s[name]).sort((a,b)=>a-b);return [name,{medianMs:median(v),p95Ms:v[Math.ceil(v.length*.95)-1],spreadMs:v.at(-1)-v[0],minMs:v[0],maxMs:v.at(-1)}]}));
}
function csv(samples,quality){
  const cols=['sample','queryToDispatchMs','observerSnapshotMs','workerRoundTripMs','workerSpanMs','replyToVisibleMs','queryToVisibleMs','nodes','edges','outputBends','outputRoutes','positionsSha256','routesSha256','environmentValid','startVisibility','startHasFocus','endVisibility','endHasFocus','nodeOverlaps','edgeCrossings','edgeNodeOverlaps','width','height','area','medianEdge','p95Edge','maxEdge','routedEdgeNodeOverlaps'];
  return cols.join(',')+'\n'+samples.map((s,i)=>{const q=quality[i],h=hashes(s.primaryJob.output);return [s.id,s.queryToDispatchMs,s.observerSnapshotMs,s.workerRoundTripMs,s.workerSpanMs,s.replyToVisibleMs,s.queryToVisibleMs,s.primaryJob.graph.nodes.length,s.primaryJob.graph.edges.length,s.primaryJob.output.bends.length,s.primaryJob.output.routes.length,h.positionsSha256,h.routesSha256,s.environmentValid,s.browserStateStart?.visibility,s.browserStateStart?.hasFocus,s.browserStateEnd?.visibility,s.browserStateEnd?.hasFocus,q.nodeOverlaps,q.edgeCrossings,q.edgeNodeOverlaps,q.width,q.height,q.area,q.medianEdge,q.p95Edge,q.maxEdge,q.routedEdgeNodeOverlaps].join(',')}).join('\n')+'\n';
}
function treeIdentity(root){
  const files=[];
  const visit=(directory,relative='')=>{
    for(const entry of readdirSync(directory,{withFileTypes:true}).sort((a,b)=>a.name.localeCompare(b.name))){
      const name=path.posix.join(relative,entry.name),file=path.join(directory,entry.name);
      if(entry.isDirectory())visit(file,name);
      else if(entry.isFile())files.push({path:name,sha256:sha256(readFileSync(file))});
    }
  };
  visit(root);return {root,sha256:sha256(JSON.stringify(files)),files};
}
async function screenshot(page,dir,name){const p=path.join(dir,'screenshot-'+name+'.png');await page.screenshot({path:p,fullPage:false});return {view:name,path:p,sha256:sha256(readFileSync(p))};}
async function shot(adapter,dir,name,origin,base){const r=await wd(origin,'GET',base+'/screenshot');const p=path.join(dir,'screenshot-'+name+'.png');writeFileSync(p,Buffer.from(r.value,'base64'));return {view:name,path:p,sha256:sha256(readFileSync(p))};}
async function freePort(){const s=createNetServer();await new Promise((r,j)=>s.once('error',j).listen(0,'127.0.0.1',r));const p=s.address().port;await new Promise(r=>s.close(r));return p;}
async function pollJson(url,timeout){const start=Date.now();while(Date.now()-start<timeout){try{const r=await fetch(url);if(r.ok)return r.json()}catch{}await new Promise(r=>setTimeout(r,100))}throw new Error('HTTP service did not start: '+url);}
async function wd(origin,method,route,body,timeoutMs=30000){const r=await fetch(origin+route,{method,headers:body===undefined?undefined:{'content-type':'application/json'},body:body===undefined?undefined:JSON.stringify(body),signal:AbortSignal.timeout(timeoutMs)});const text=await r.text();const data=text?JSON.parse(text):{};if(!r.ok||data.value?.error)throw new Error(method+' '+route+' HTTP '+r.status+' '+text);return data;}
async function withWatchdog(promise,timeoutMs,label){let timer;try{return await Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error(label+' watchdog expired after '+timeoutMs+'ms')),timeoutMs);})]);}finally{clearTimeout(timer);}}
function parseArgs(argv){const o={};for(let i=0;i<argv.length;i++){const a=argv[i];if(a==='--help'){console.log('Use --input-results JSON --source input.ttl --browser chrome|safari|webkit --output NEW-DIR [--warmups 2 --repeats 7 --viewport 800x600 --theme light --profile true] [--safari-driver-origin URL --safari-session-id ID --safari-idle-url URL --safari-browser-version VERSION]');process.exit(0)}if(!a.startsWith('--'))throw new Error('Unexpected argument '+a);const k=a.slice(2);if(k==='show-values'&&(argv[i+1]===undefined||argv[i+1].startsWith('--'))){o[k]='true';continue}o[k]=argv[++i];if(!o[k]||o[k].startsWith('--'))throw new Error('Missing value for '+a)}return o;}
function parseViewport(v){const m=/^(\d+)x(\d+)$/.exec(v);if(!m)throw new Error('Viewport must be WIDTHxHEIGHT');return {width:Number(m[1]),height:Number(m[2])};}
function median(v){const i=Math.floor(v.length/2);return v.length%2?v[i]:(v[i-1]+v[i])/2;}
function sha256(v){return createHash('sha256').update(v).digest('hex');}
